import './neon-session-timeout-warning.scss';
import { NeonWidget, bindCallback, getCallback } from '../shared/neon-widget';
import { dynamicText, createElement, updateDynamicText, updateDynamicAttribute, dynamicAttr, updateConditionalElements, useElementIf, getClosest } from '../shared/dom-manipulation';
import { addTranslationListener, getCurrentTranslations, translate } from '@ps-refarch-ux/mfe-utils';
import { getNumberFromLocalStorage } from '../shared/local-storage-utils';
// The neon-session-timeout-warning component is a modal that appears after 25 minutes of inactivity.
//
// In out case inactivity means not clicking the mouse or pressing any keyboard keys
// scrolling, hovering, admiring etc are actions one can take that will NOT count as being active.
//
// When this component mounts the 25 minute warningTimer starts
// After the initial 25 minutes (warningTimer) the modal displays and the logoutTimer starts counting down.
// After an additional 5 minute, logoutTimer times out, dispatching a `neonSessionTimeoutWarningLogout` event for a listener to handle a logout action
//
// Updates from PDS-3801
// When ever the warning time resets, it stamps the current time into localStorage.
// When either the warning or logout timers expire, before doing their default behavior, they first check
// the elapsed time to make sure an instance in another tab hasn't already reset the timer.
// If there should still be time left, it restarts the timer with the exact amount of remaining time.
export class NeonSessionTimeoutWarning extends NeonWidget {
    constructor() {
        super();
        this.widgetTag = 'neon-session-timeout-warning';
        this.showTimeoutWarning = false;
        if (document.querySelector('[neon-session-timeout-warning]') != null) {
            console.error('There is already a neon-session-timeout-warning present. This component is restricted to one on a page at a time');
        }
        getCurrentTranslations();
    }
    //Any attribute that should be watched for changes should be listed here.
    static get observedAttributes() {
        return [
            'data-dialog-header-text',
            'data-warning-header-text',
            'data-warning-message-text',
            'data-sign-out-button-text',
            'data-stay-signed-in-button-text',
            'data-warning-time',
            'data-logout-time',
        ];
    }
    //when the attributes change this will run
    attributeChanged(attrName, oldVal, newVal) {
        super.attributeChanged(attrName, oldVal, newVal);
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        switch (attrName) {
            case 'data-dialog-header-text':
            case 'data-warning-header-text':
            case 'data-warning-header-message':
                updateDynamicText(this);
                break;
            case 'data-sign-out-button-text':
            case 'data-stay-signed-in-button-text':
                updateDynamicAttribute(this, 'data-text'); // updates button data-text
                break;
            case 'data-warning-time':
            case 'data-logout-time':
                this.resetTimers();
                break;
            default:
        }
    }
    // The default time before the warning is shown is 25 minutes
    //Returns the warning time in milliseconds
    getWarningTime() {
        const warningTime = !isNaN(Number(this.getAttribute('data-warning-time'))) && Number(this.getAttribute('data-warning-time')) > 0 ? Number(this.getAttribute('data-warning-time')) : 25;
        return warningTime * 60000;
    }
    // the logoutTime is the time till automatic logout after the warning timer goes off. the default is 5 minutes
    //Returns the logout time in milliseconds
    getLogoutTime() {
        const logoutTime = !isNaN(Number(this.getAttribute('data-logout-time'))) && Number(this.getAttribute('data-logout-time')) > 0 ? Number(this.getAttribute('data-logout-time')) : 5;
        return logoutTime * 60000;
    }
    // start the timer, after this.warningTime we display the warning dialog, and start the logout timer
    startWarningTimer(warningTime) {
        if (warningTime == null) {
            localStorage.setItem('neon-session-timeout-warning:start-time', String(Date.now()));
        }
        if (this.warningTimer != null) {
            clearTimeout(this.warningTimer);
            delete this.warningTimer;
        }
        if (this.logoutTimer != null) {
            clearTimeout(this.logoutTimer);
            delete this.logoutTimer;
        }
        this.warningTimer = setTimeout(() => {
            delete this.warningTimer;
            const timeRemaining = this.getRemainingWarningTime();
            if (timeRemaining > 0) {
                this.startWarningTimer(timeRemaining);
            }
            else {
                // show the warning modal
                this.showTimeoutWarning = true;
                updateConditionalElements(this);
                // and start the logout timer
                this.startLogoutTimer();
                this.dispatchEvent(new CustomEvent('neonSessionTimeoutWarningLogoutWarningTimerStart', { bubbles: true }));
            }
        }, warningTime || this.getWarningTime());
    }
    //Returns the remaining time before the session warning should happen based on the elapsed time from the localStorage variable.
    //The return time is in milliseconds
    getRemainingWarningTime() {
        const elapsedTime = this.getElapsedTime();
        if (elapsedTime == null) {
            return 0;
        }
        //Note, if too much time has been elapsed, time remaining will be negative.
        const timeRemaining = this.getWarningTime() - elapsedTime;
        //If the timeRemaining is negative, then 0 will be returned.
        return Math.max(0, timeRemaining);
    }
    //Returns the remaining time before the session logout should happen based on the elapsed time from the localStorage variable.
    //The return time is in milliseconds
    getRemainingLogoutTime() {
        const elapsedTime = this.getElapsedTime();
        if (elapsedTime == null) {
            return 0;
        }
        //Note, if too much time has been elapsed, time remaining will be negative.
        const timeRemaining = (this.getWarningTime() + this.getLogoutTime()) - elapsedTime;
        //If the timeRemaining is negative, then 0 will be returned.
        return Math.max(0, timeRemaining);
    }
    getElapsedTime() {
        const startTime = getNumberFromLocalStorage('neon-session-timeout-warning:start-time');
        if (startTime != null) {
            return Date.now() - startTime;
        }
    }
    // This is called after this.warningTimer times out
    //if logoutTime is provided, that is how long the timer will be.
    //logoutTime is in milliseconds.
    startLogoutTimer(logoutTime) {
        if (this.logoutTimer != null) {
            clearTimeout(this.logoutTimer);
            delete this.logoutTimer;
        }
        this.logoutTimer = setTimeout(() => {
            delete this.logoutTimer;
            const remainingWarningTime = this.getRemainingWarningTime();
            const remainingLogoutTime = this.getRemainingLogoutTime();
            if (remainingWarningTime > 0) {
                //There is remaining warning time. That means we need to start the warning timer again.
                this.startWarningTimer(remainingWarningTime);
                this.showTimeoutWarning = false;
                updateConditionalElements(this);
                return;
            }
            else if (remainingLogoutTime) {
                this.startLogoutTimer(remainingLogoutTime);
                return;
            }
            this.sessionSignOut();
        }, logoutTime || this.getLogoutTime());
    }
    // resetTimers resets BOTH warning modal timer AND the logout timer
    resetTimers(event) {
        // check to see if the click event is coming from the warning itself.
        // we do not want to reset the timer on click if the warning dialog is visible
        // we also do not want a keypress (tab, enter, space) to close the warning dialog/have that keypress reset the timers while the modal is visible
        const clickFromWarningMessage = getClosest(event === null || event === void 0 ? void 0 : event.target, 'neon-2_20_1-session-timeout-warning');
        if (clickFromWarningMessage == null || ((event === null || event === void 0 ? void 0 : event.type) === 'keydown' && this.showTimeoutWarning === false)) {
            this.startWarningTimer();
            this.showTimeoutWarning = false;
            updateConditionalElements(this);
        }
    }
    sessionSignOut() {
        this.dispatchEvent(new CustomEvent('neonSessionTimeoutWarningLogout', { bubbles: true }));
    }
    renderSessionTimeoutWarning() {
        return createElement('neon-2_20_1-modal-dialog', {
            attrs: {
                'data-type': 'security',
                'data-animate': 'true',
                'data-show-close-button': 'false'
            },
            listeners: {
                'neonDialogHasClosed': () => { return this.resetTimers(); },
            }
        }, createElement('div', {
            text: dynamicText(() => { return this.getAttribute('data-dialog-header-text') || translate('neon|session-timeout-warning|Session timeout'); }),
            attrs: {
                'data-slot': 'dialog-header-title'
            }
        }), createElement('div', {
            attrs: {
                'data-slot': 'dialog-body'
            }
        }, 
        // TODO: replace with neon-illustration component
        createElement('img', {
            attrs: {
                'src': 'https://assets.powerschool.com/neon/unversioned/svg/error/Timeout.svg',
                'aria-label': dynamicAttr(() => { return translate('neon|error|408|imageAlt|Person sitting with a laptop in front of a large hourglass'); }),
            }
        }), createElement('div', {
            attrs: {
                'class': 'neon-session-timeout-warning-text'
            }
        }, createElement('h2', {
            text: dynamicText(() => { return this.getAttribute('data-warning-header-text') || translate('neon|session-timeout-warning|Your session will expire soon'); }),
            attrs: {
                'class': 'neon-session-timeout-warning-heading'
            }
        }), createElement('p', {
            text: dynamicText(() => { return this.getAttribute('data-warning-message-text') || translate('neon|session-timeout-warning|You will be signed out in five minutes due to inactivity.'); }),
            attrs: {
                'class': 'neon-session-timeout-warning-message'
            }
        }))), createElement('div', {
            attrs: {
                'data-slot': 'dialog-footer-content'
            }
        }, createElement('neon-2_20_1-button', {
            attrs: {
                'id': 'neon-session-timeout-warning-sign-out',
                'data-type': 'secondary',
                'data-text': dynamicAttr(() => { return this.getAttribute('data-sign-out-button-text') || translate('neon|session-timeout-warning|Sign out'); })
            },
            listeners: {
                'click': () => {
                    this.sessionSignOut();
                }
            }
        }), createElement('neon-2_20_1-button', {
            attrs: {
                'id': 'neon-session-timeout-warning-stay-signed-in',
                'data-type': 'primary',
                'data-text': dynamicAttr(() => { return this.getAttribute('data-stay-signed-in-button-text') || translate('neon|session-timeout-warning|Stay signed in'); })
            },
            listeners: {
                'click': (event) => {
                    event.target.dispatchEvent(new CustomEvent('neonDialogClose', { bubbles: true }));
                }
            }
        })));
    }
    render() {
        return useElementIf(() => { return this.showTimeoutWarning; }, () => { return this.renderSessionTimeoutWarning(); });
    }
    connectedCallback() {
        super.connectedCallback();
        this.startWarningTimer();
        // on user input we reset the session timeout timers
        window.addEventListener('click', bindCallback(this.resetTimers, this));
        window.addEventListener('keydown', bindCallback(this.resetTimers, this));
        this.i18nUnsubscribe = addTranslationListener(() => {
            updateDynamicText(this);
            updateDynamicAttribute(this, 'data-text');
            updateDynamicAttribute(this, 'aria-label'); // alt text on the image, may need to be removed once we have an illustration component
        });
    }
    disconnectedCallback() {
        // remove the event listener
        window.removeEventListener('click', getCallback(this.resetTimers, this));
        window.removeEventListener('keydown', getCallback(this.resetTimers, this));
        // clear the timeouts
        if (this.logoutTimer != null) {
            clearTimeout(this.logoutTimer);
            delete this.logoutTimer;
        }
        if (this.warningTimer != null) {
            clearTimeout(this.warningTimer);
            delete this.warningTimer;
        }
        if (this.i18nUnsubscribe != null) {
            this.i18nUnsubscribe();
            this.i18nUnsubscribe = undefined;
        }
    }
}
